DO $backfill$
DECLARE
  -- Status cujo dono é o Omie (cópia de STATUS_GERIDO_OMIE / c_status_omie de
  -- reconciliar_pedidos_omie), menos o próprio 'cancelado'.
  c_alvo  constant text[] := ARRAY['importado','separacao','enviado','faturado'];
  v_oben  int;
  v_col   int;
  v_alvo  int;
  v_n     int;
  r       record;
BEGIN
  SELECT count(*) FILTER (WHERE conta = 'oben'), count(*) FILTER (WHERE conta = 'colacor')
    INTO v_oben, v_col FROM _pv_cancelado_omie;
  -- A lista é a que foi medida — nem truncada nem trocada no caminho.
  IF v_oben IS DISTINCT FROM 3436 OR v_col IS DISTINCT FROM 10368 THEN
    RAISE EXCEPTION 'backfill-cancelado: lista embutida divergente (oben %, colacor %; esperado 3436/10368)',
      v_oben, v_col;
  END IF;

  FOR r IN
    SELECT so.account, so.status, count(*) AS n, round(sum(so.total), 2) AS rs
      FROM public.sales_orders so
      JOIN _pv_cancelado_omie c ON c.conta = so.account AND c.pid = so.omie_pedido_id
     WHERE so.deleted_at IS NULL AND so.status = ANY (c_alvo)
     GROUP BY 1, 2 ORDER BY 1, 2
  LOOP
    RAISE NOTICE 'backfill-cancelado ANTES: % % → cancelado: % pedido(s), R$ %', r.account, r.status, r.n, r.rs;
  END LOOP;

  SELECT count(*) INTO v_alvo
    FROM public.sales_orders so
    JOIN _pv_cancelado_omie c ON c.conta = so.account AND c.pid = so.omie_pedido_id
   WHERE so.deleted_at IS NULL AND so.status = ANY (c_alvo);

  UPDATE public.sales_orders so
     SET status = 'cancelado'
    FROM _pv_cancelado_omie c
   WHERE c.conta = so.account
     AND c.pid = so.omie_pedido_id
     AND so.deleted_at IS NULL
     AND so.status = ANY (c_alvo);
  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF v_n IS DISTINCT FROM v_alvo THEN
    RAISE EXCEPTION 'backfill-cancelado: atualizou % linha(s), alvo medido %', v_n, v_alvo;
  END IF;
  RAISE NOTICE 'backfill-cancelado: % linha(s) → cancelado', v_n;
END
$backfill$;

-- O trigger de coerência do agregado (`trg_pedido_venda_coerencia_cab`) é DEFERRED: sem isto ele
-- só roda no COMMIT, e o `--ensaio` (ROLLBACK) passaria verde com uma linha legada incoerente que
-- derrubaria o apply real (challenge Codex 2026-11-22). IMMEDIATE = o 23514 aparece no ensaio.
SET CONSTRAINTS public.trg_pedido_venda_coerencia_cab IMMEDIATE;

-- POSTCONDIÇÃO: nenhum pedido que o Omie marca como cancelado segue no universo de venda
-- (o universo exclui STATUS_NAO_VENDA = cancelado/rascunho/pendente/orcamento,
-- src/lib/farmer/universo-pedidos.ts).
DO $post$
DECLARE
  v_resto int;
BEGIN
  SELECT count(*) INTO v_resto
    FROM public.sales_orders so
    JOIN _pv_cancelado_omie c ON c.conta = so.account AND c.pid = so.omie_pedido_id
   WHERE so.deleted_at IS NULL
     AND (so.status IS NULL OR so.status <> ALL (ARRAY['cancelado','rascunho','pendente','orcamento']));
  IF v_resto IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION 'backfill-cancelado POSTCONDIÇÃO: % pedido(s) cancelado(s) no Omie ainda no universo de venda', v_resto;
  END IF;
  RAISE NOTICE 'backfill-cancelado POSTCONDIÇÃO OK: 0 pedido cancelado no Omie no universo de venda';
END
$post$;
